INSERT INTO feature VALUES('math-path','modules','The mathematical library''s path algebra','packages','implemented','ordinary',NULL,'`std.math.path`, the first module of `std.math`, the standard library''s mathematics, writes composition, `join`, and a function''s action, `ap`, with their endpoints stated, so a type over a reflexivity or a variable function states its paths, beside `apd`, a dependent function''s action; the associator `assoc` and the unitors `leftUnit` and `rightUnit` are the groupoid laws of composition, each a definition at its path type proved by based path induction or by conversion, which the kernel replays, the associator by conversion since both nestings of a chain move along each path in turn; the whiskers `whiskerLeft` and `whiskerRight` are the level-two composites over the 2-chain, one column holding the 2-cell, the lifts `fill` writes a square''s sides with; `apComp` is `ap`''s functoriality, and `natural` is a homotopy''s naturality along a path, the naturality operation at one variable, each by based path induction on the path.',NULL,'library/std/src/math/path.gandr','corpus/ledger/features/math-path.gandr',NULL);
